def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    from collections import Counter
    cnt=Counter(x for row in g for x in row)
    bg=cnt.most_common(1)[0][0]
    nonbg=[c for c,_ in cnt.items() if c!=bg]
    A=None
    for r in range(h):
        if g[r][0]!=bg: A=g[r][0]; break
        if g[r][-1]!=bg: A=g[r][-1]; break
    S=[c for c in nonbg if c!=A][0]
    acells=[(r,c) for r in range(h) for c in range(w) if g[r][c]==A]
    seeds=[(r,c) for r in range(h) for c in range(w) if g[r][c]==S]
    rowsA=sorted({r for r,c in acells}); colsA=sorted({c for r,c in acells})
    def contiguous(v): return v==list(range(v[0],v[-1]+1))
    def groups(v):
        gs=[]; cur=[v[0]]
        for x in v[1:]:
            if x==cur[-1]+1: cur.append(x)
            else: gs.append(cur); cur=[x]
        gs.append(cur); return gs
    def fill_ray(r,c,dr,dc):
        while True:
            r+=dr; c+=dc
            if not (0<=r<h and 0<=c<w): return
            if g[r][c]==S: out[r][c]=S+3; return
            if g[r][c]==bg: out[r][c]=S
            else: return
    colgroups=groups(colsA) if contiguous(rowsA) else None
    rowgroups=groups(rowsA) if contiguous(colsA) else None
    if colgroups and len(colgroups)==2 and all(len(x)==len(colgroups[0]) for x in colgroups):
        # vertical bars: left col group, right col group; spans of rows per bar
        gl,gr=colgroups[0],colgroups[-1]
        span_l=(min(r for r,c in acells if c==gl[0]), max(r for r,c in acells if c==gl[0]))
        span_r=(min(r for r,c in acells if c==gr[-1]), max(r for r,c in acells if c==gr[-1]))
        offs_l=set(); offs_r=set()
        for sr,sc in seeds:
            if span_l[0]<=sr<=span_l[1]: offs_l.add(sr-span_l[0])
            if span_r[0]<=sr<=span_r[1]: offs_r.add(sr-span_r[0])
        for off in offs_l:
            if off < len(gr): fill_ray(span_l[0]+off, gl[0], 0, 1)   # own rows
        # mapped offsets: offset of seed in its own bar applied to the other bar
        for off in offs_r:
            if off < len(gl): fill_ray(span_r[0]+off, gr[-1], 0, -1)
        for off in offs_l:
            if off < len(gr): fill_ray(span_r[0]+off, gr[-1], 0, -1) # left-bar seeds -> right bar
        for off in offs_r:
            if off < len(gl): fill_ray(span_l[0]+off, gl[0], 0, 1)   # right-bar seeds -> left bar
    elif rowgroups and len(rowgroups)==2 and all(len(x)==len(rowgroups[0]) for x in rowgroups):
        gt,gb=rowgroups[0],rowgroups[-1]
        span_t=(min(c for r,c in acells if r==gt[0]), max(c for r,c in acells if r==gt[0]))
        span_b=(min(c for r,c in acells if r==gb[-1]), max(c for r,c in acells if r==gb[-1]))
        offs_t=set(); offs_b=set()
        for sr,sc in seeds:
            if span_t[0]<=sc<=span_t[1]: offs_t.add(sc-span_t[0])
            if span_b[0]<=sc<=span_b[1]: offs_b.add(sc-span_b[0])
        for off in offs_b:
            fill_ray(gb[-1], span_b[0]+off, -1, 0)   # bottom bar own
            if off < len(gt): fill_ray(gt[0], span_t[0]+off, 1, 0)  # mapped to top
        for off in offs_t:
            fill_ray(gt[0], span_t[0]+off, 1, 0)
            if off < len(gb): fill_ray(gb[-1], span_b[0]+off, -1, 0)
    return out
